{
  "status": "SUPPORTED",
  "task_summary": "Retrieve fasteners from storage, attach them to the workpiece at the marked location using a tool, then place the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastener_component",
        "entity_kind": "OBJECT",
        "function": "The physical part to be attached to the workpiece.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "pin", "washer"],
        "required_properties": ["fits_marked_location", "secure_workpiece"]
      },
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "The base object receiving the fastener.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["table", "panel", "frame"],
        "required_properties": ["has_marked_location"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to secure the fastener.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "gripper"],
        "required_properties": ["can_secure_fastener"]
      },
      {
        "id": "marked_location",
        "entity_kind": "REGION",
        "function": "The specific spot on the workpiece requiring fastening.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["hole", "slot", "attachment_point"],
        "required_properties": ["is_marked"]
      },
      {
        "id": "storage_area",
        "entity_kind": "FIXED_TARGET",
        "function": "A closed structure containing the fasteners or tools.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["cabinet", "drawer", "tray"],
        "required_properties": ["holds_components", "can_be_opened"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The surface where the tool is placed after use.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tabletop", "desk"],
        "required_properties": ["is_workbench"]
      }
    ],
    "functional_relations": [
      {
        "id": "compatible_with",
        "relation": "The fastener component fits into the marked location.",
        "participant_roles": [
          "fastener_component",
          "marked_location"
        ]
      ,
        "required": true
      },
      {
        "id": "secured_to",
        "relation": "The fastener component is attached to the workpiece.",
        "participant_roles": [
          "fastener_component",
          "workpiece"
        ]
      ,
        "required": true
      },
      {
        "id": "placed_on",
        "relation": "The fastening tool rests on the workbench surface.",
        "participant_roles": [
          "fastening_tool",
          "workbench_surface"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "retrieve_fastener",
        "operation": "Locate and retrieve the fastener component from the storage area.",
        "participant_roles": [
          "fastener_component",
          "storage_area"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "Attach the fastener component to the workpiece using the fastening tool.",
        "participant_roles": [
          "fastener_component",
          "workpiece",
          "fastening_tool"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "deposit_tool",
        "operation": "Place the fastening tool on the workbench surface.",
        "participant_roles": [
          "fastening_tool",
          "workbench_surface"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastener_component": [],
      "workpiece": [
        {
          "label": "table",
          "visual_description": "Wooden table with drawers and a cabinet on top."
        }
      ],
      "fastening_tool": [],
      "marked_location": [],
      "storage_area": [
        {
          "label": "cabinet",
          "visual_description": "Blue cabinet standing on the table."
        },
        {
          "label": "drawer",
          "visual_description": "Two drawers under the table."
        },
        {
          "label": "tray",
          "visual_description": "Black tray with yellow/blue items on the table."
        }
      ],
      "workbench_surface": [
        {
          "label": "tabletop",
          "visual_description": "The wooden surface of the table."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "storage_area",
        "label": "cabinet",
        "visual_description": "Blue cabinet on table.",
        "reason": "Likely contains fasteners or tools."
      },
      {
        "id": "storage_area",
        "label": "drawer",
        "visual_description": "Drawers under table.",
        "reason": "Likely contains fasteners or tools."
      },
      {
        "id": "storage_area",
        "label": "tray",
        "visual_description": "Tray on table.",
        "reason": "Contains items that might be components."
      }
    ],
    "inspection_order": [
      "storage_area",
      "marked_location",
      "workbench_surface"
    ]
  }
  ,
  "unsupported_reason": "",
  "schema_version": 3
}
